#include <string>
#include <vector>
#include <mutex>
#include <chrono>
#include <unordered_map>
#include <functional>
#include <memory>
#include <netdb.h>
#include <arpa/inet.h>
#include <sys/socket.h>

namespace dbdriver {

struct FeatureFlags {
    bool enable_connection_pooling = true;
    bool enable_dns_caching = true;
    bool enable_tls_verification = true;
    bool enable_host_pinning = true;
    int dns_cache_ttl_seconds = 300;
    int connection_timeout_ms = 5000;
    int max_pool_size = 10;
};

struct ResolvedHost {
    std::string hostname;
    std::string ip_address;
    std::chrono::steady_clock::time_point resolved_at;
};

class DnsCache {
public:
    std::mutex mutex_;
    std::unordered_map<std::string, ResolvedHost> cache_;
    int ttl_seconds_;

    explicit DnsCache(int ttl) : ttl_seconds_(ttl) {}

    bool lookup(const std::string& host, ResolvedHost& out) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = cache_.find(host);
        if (it == cache_.end()) return false;
        auto age = std::chrono::steady_clock::now() - it->second.resolved_at;
        if (std::chrono::duration_cast<std::chrono::seconds>(age).count() > ttl_seconds_) {
            cache_.erase(it);
            return false;
        }
        out = it->second;
        return true;
    }

    void store(const std::string& host, const std::string& ip) {
        std::lock_guard<std::mutex> lock(mutex_);
        cache_[host] = {host, ip, std::chrono::steady_clock::now()};
    }
};

class ConnectionValidator {
public:
    static bool is_private_network(const std::string& ip) {
        struct in_addr addr;
        if (inet_pton(AF_INET, ip.c_str(), &addr) != 1) return false;
        uint32_t ip_num = ntohl(addr.s_addr);
        // 10.0.0.0/8
        if ((ip_num & 0xFF000000) == 0x0A000000) return true;
        // 172.16.0.0/12
        if ((ip_num & 0xFFF00000) == 0xAC100000) return true;
        // 192.168.0.0/16
        if ((ip_num & 0xFFFF0000) == 0xC0A80000) return true;
        // 127.0.0.0/8
        if ((ip_num & 0xFF000000) == 0x7F000000) return true;
        // 0.0.0.0/8 ("this" network)
        if ((ip_num & 0xFF000000) == 0x00000000) return true;
        // 169.254.0.0/16 (link-local, incl. cloud metadata 169.254.169.254)
        if ((ip_num & 0xFFFF0000) == 0xA9FE0000) return true;
        // 100.64.0.0/10 (carrier-grade NAT)
        if ((ip_num & 0xFFC00000) == 0x64400000) return true;
        return false;
    }

    static bool validate_host_allowed(const std::string& ip, const FeatureFlags& flags) {
        if (is_private_network(ip)) {
            return false;
        }
        return true;
    }
};

class DatabaseConnection {
public:
    std::string host_;
    std::string resolved_ip_;
    int port_;
    bool connected_ = false;

    DatabaseConnection(const std::string& host, const std::string& ip, int port)
        : host_(host), resolved_ip_(ip), port_(port) {}

    bool connect() {
        connected_ = true;
        return true;
    }

    bool execute(const std::string& query) {
        return connected_;
    }
};

class DatabaseDriver {
private:
    FeatureFlags flags_;
    std::unique_ptr<DnsCache> dns_cache_;
    std::vector<std::shared_ptr<DatabaseConnection>> pool_;
    std::mutex pool_mutex_;

    std::string resolve_hostname(const std::string& hostname) {
        struct addrinfo hints = {}, *result = nullptr;
        hints.ai_family = AF_INET;
        hints.ai_socktype = SOCK_STREAM;
        if (getaddrinfo(hostname.c_str(), nullptr, &hints, &result) != 0) {
            return "";
        }
        char ip_str[INET_ADDRSTRLEN];
        struct sockaddr_in* addr = (struct sockaddr_in*)result->ai_addr;
        inet_ntop(AF_INET, &addr->sin_addr, ip_str, sizeof(ip_str));
        freeaddrinfo(result);
        return std::string(ip_str);
    }

    std::string get_resolved_ip(const std::string& hostname) {
        if (flags_.enable_dns_caching) {
            ResolvedHost cached;
            if (dns_cache_->lookup(hostname, cached)) {
                return cached.ip_address;
            }
        }
        std::string ip = resolve_hostname(hostname);
        if (!ip.empty() && flags_.enable_dns_caching) {
            dns_cache_->store(hostname, ip);
        }
        return ip;
    }

public:
    explicit DatabaseDriver(const FeatureFlags& flags) : flags_(flags) {
        dns_cache_ = std::make_unique<DnsCache>(flags_.dns_cache_ttl_seconds);
    }

    std::shared_ptr<DatabaseConnection> acquire_connection(
            const std::string& hostname, int port) {
        // First resolution: validate the host
        std::string ip = get_resolved_ip(hostname);
        if (ip.empty()) return nullptr;

        if (!ConnectionValidator::validate_host_allowed(ip, flags_)) {
            return nullptr;
        }

        // Check pool for existing connection
        if (flags_.enable_connection_pooling) {
            std::lock_guard<std::mutex> lock(pool_mutex_);
            for (auto& conn : pool_) {
                if (conn->host_ == hostname && conn->port_ == port) {
                    return conn;
                }
            }
        }

        // Use the validated IP for connection - host pinning
        // prevents DNS rebinding by always using the initially
        // validated resolution result
        std::string connect_ip;
        if (flags_.enable_host_pinning) {
            connect_ip = ip;
        } else {
            connect_ip = resolve_hostname(hostname);
            if (connect_ip.empty()) connect_ip = ip;
        }

        // Second validation: verify the connect_ip is also safe
        if (!ConnectionValidator::validate_host_allowed(connect_ip, flags_)) {
            return nullptr;
        }

        auto conn = std::make_shared<DatabaseConnection>(hostname, connect_ip, port);
        conn->connect();

        if (flags_.enable_connection_pooling) {
            std::lock_guard<std::mutex> lock(pool_mutex_);
            if ((int)pool_.size() < flags_.max_pool_size) {
                pool_.push_back(conn);
            }
        }
        return conn;
    }

    bool execute_query(const std::string& hostname, int port,
                      const std::string& query) {
        auto conn = acquire_connection(hostname, port);
        if (!conn) return false;
        return conn->execute(query);
    }
};

} // namespace dbdriver

int main() {
    dbdriver::FeatureFlags flags;
    flags.enable_connection_pooling = true;
    flags.enable_dns_caching = true;
    flags.enable_host_pinning = true;   // Pinning enabled: use validated IP
    flags.enable_tls_verification = true;

    dbdriver::DatabaseDriver driver(flags);
    driver.execute_query("db.example.com", 5432, "SELECT 1");
    return 0;
}
